#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> PI;
typedef long long LL;
#define FI first
#define SE second
#define MP make_pair
#define PB push_back
#define REP(I,N) for(int I=0;I<N;I++)
#define FOR(I,A,B) for(int I=A;I<B;I++)
#define ROLL(I,N) for(int I=N-1;I>=0;I--)
#define readInt(A) scanf("%d",&A)
#define readPair(A,B) scanf("%d%d",&A,&B)
const int MAX = 31;
const int MOD = 1e9 + 7;
int n;
LL mat[MAX][MAX];
struct Matrix {
    LL t[MAX][MAX];
    void setIdentity() {
        REP(i,n) REP(j,n) t[i][j] = (i==j);
    }
    void multiply(Matrix& b) {
        REP(i,n) REP(j,n) mat[i][j] = 0;
        REP(i,n) REP(j,n) REP(k,n)
            mat[i][k] += t[i][j] * b.t[j][k] % MOD;
        REP(i,n) REP(j,n) t[i][j] = mat[i][j] % MOD;
    }
};
LL mVal;
LL pw[MAX];
LL res[MAX];
int kVal;
vector<LL> digitsArr;
int main() {
    LL m_in; int k_in;
    scanf("%lld%d", &m_in, &k_in);
    mVal = m_in; kVal = k_in;
    while (mVal) {
        digitsArr.PB(mVal % kVal);
        mVal /= kVal;
    }
    n = kVal + 1;
    Matrix base, identity;
    REP(i,kVal) base.t[i][(i+1)%kVal] = 1;
    base.t[kVal][kVal] = 1;
    identity.setIdentity();
    REP(i,kVal+1) {
        base.t[0][i] = 1;
        base.t[i][i] = 1;
    }
    vector<Matrix> dMat(digitsArr.size());
    dMat[0] = identity;
    dMat[0].multiply(base);
    FOR(i,1,(int)digitsArr.size()) {
        dMat[i] = dMat[i-1];
        REP(_,kVal) dMat[i].multiply(dMat[i]);
        dMat[i].multiply(base);
    }
    REP(i,n) res[i] = 1;
    for (int idx = (int)digitsArr.size() - 1; idx >= 0; idx--) {
        REP(_, digitsArr[idx]) {
            REP(i,n) pw[i] = 0;
            REP(i,n) REP(j,n) pw[j] += res[i] * dMat[idx].t[i][j] % MOD;
            REP(i,n) res[i] = pw[i] % MOD;
        }
    }
    printf("%lld\n", res[kVal]);
}
